-- ============================================================
-- Migration 7: Tipologias Oficiais SMIIC
-- 5 Macro-Áreas de Nível 1 + 143 Subcategorias de Nível 2
-- Conforme padrão oficial da SECTUR / SMIIC
-- ============================================================

-- 1. Inserir ou atualizar Tipologia 1 (Nível 1 - 5 Macro-categorias Raiz)
ON CONFLICT (slug, context) DO UPDATE SET
  name = EXCLUDED.name,
  sort_order = EXCLUDED.sort_order;

-- 2. Inserir ou atualizar Tipologia 2 (Nível 2 - 143 Categorias filhas)
ON CONFLICT (slug, context) DO UPDATE SET
  name = EXCLUDED.name,
  parent_id = EXCLUDED.parent_id,
  sort_order = EXCLUDED.sort_order;
